// ───────────────────────────────────────────────────────────────
// APPLY PATCHES (WITH DIAGNOSTICS)
// ───────────────────────────────────────────────────────────────

const OBSIDIAN_BASE = 'https://10.1.1.200:27124';
const token = $('Config - Paths').first().json.obsidianToken;

const briefingRaw = $('Fetch Briefing').first().json.data;
const projectIndexRaw = $('Fetch Project Index').first().json.data;

// Helper: GET a file from Obsidian
async function obsidianGet(path) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${OBSIDIAN_BASE}/vault/${path}`,
    headers: { 'Authorization': 'Bearer ' + token },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    skipSslCertificateValidation: true
  });
  if (response.statusCode !== 200) throw new Error(`HTTP ${response.statusCode}`);
  return response.body;
}

// Helper: PUT a file to Obsidian
async function obsidianPut(path, content) {
  const response = await this.helpers.httpRequest({
    method: 'PUT',
    url: `${OBSIDIAN_BASE}/vault/${path}`,
    headers: {
      'Authorization': 'Bearer ' + token,
      'Content-Type': 'text/markdown'
    },
    body: content,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    skipSslCertificateValidation: true
  });
  if (response.statusCode >= 300) throw new Error(`HTTP ${response.statusCode}`);
}

// 1. Parse project index
const cleanJson = projectIndexRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const projects = JSON.parse(cleanJson);
const projectMap = {};
for (const p of projects) {
  projectMap[p.id] = p.file_name;
}

// 2. Parse briefing for all callouts
const lines = briefingRaw.split('\n');
const calloutBlocks = [];
let currentBlock = null;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (/^>\s*\[!info\]\s*Proposed project file update/i.test(line)) {
    if (currentBlock) {
      currentBlock.endIdx = i - 1;
      calloutBlocks.push(currentBlock);
    }
    currentBlock = { startIdx: i, lines: [line] };
  } else if (currentBlock) {
    if (line.startsWith('>')) {
      currentBlock.lines.push(line);
    } else {
      currentBlock.endIdx = i - 1;
      calloutBlocks.push(currentBlock);
      currentBlock = null;
    }
  }
}
if (currentBlock) {
  currentBlock.endIdx = lines.length - 1;
  calloutBlocks.push(currentBlock);
}

// 3. STRICT CHECKBOX FILTER
const approvedBlocks = calloutBlocks.filter(block => {
  const blockText = block.lines.join('\n');
  return /^>\s*-\s*\[[xX]\]\s*Apply this update/m.test(blockText);
});

// DIAGNOSTIC OUTPUT: If it stops here, it truly saw 0 checked boxes.
if (approvedBlocks.length === 0) {
  return [{ 
    json: { 
      status: 'no_approved_patches', 
      message: 'Workflow stopped correctly. No [x] checkboxes were found in the parsed data.',
      patches_applied: 0, 
      total_callouts_found: calloutBlocks.length,
      debug_raw_input_preview: briefingRaw.substring(0, 500) + '...', // Check if n8n has stale data
      debug_blocks_seen: calloutBlocks.map(b => b.lines.join('\n')) // Look at what n8n actually read
    } 
  }];
}

// 4. Extract data from approved blocks
const patches = [];
for (const block of approvedBlocks) {
  const blockText = block.lines.join('\n');
  const idMatch = blockText.match(/^>\s*project-id::\s*(.+)$/m);
  if (!idMatch) continue;
  const projectId = idMatch[1].trim();

  let proposedStatus = '';
  const statusMatch = blockText.match(/^>\s*(?:\*\*)?Updated Status(?:\*\*)?[:\s]*\n((?:>.*\n?)*?)(?=>\s*\n|>\s*(?:\*\*)?New tasks(?:\*\*)?|$)/m);
  if (statusMatch) {
    proposedStatus = statusMatch[1]
      .split('\n')
      .map(l => l.replace(/^>\s?/, '').trim())
      .filter(l => l.length > 0)
      .join('\n');
  }

  const newTasks = [];
  let inNewTasks = false;
  for (const line of block.lines) {
    if (/(?:\*\*)?New tasks(?:\*\*)?/.test(line)) { inNewTasks = true; continue; }
    if (inNewTasks) {
      const normLine = line.replace(/^>\s*>\s*/, '> ');
      if (/^>\s*-\s*\[\s*\]\s*.+/.test(normLine)) {
        newTasks.push(normLine.replace(/^>\s*/, '').trim());
      }
    }
  }
  patches.push({ projectId, proposedStatus, newTasks, block });
}

// 5. Update individual project files
let appliedCount = 0;
const errors = [];

for (const patch of patches) {
  const fileName = projectMap[patch.projectId];
  if (!fileName) {
    errors.push(`No file found for project-id: ${patch.projectId}`);
    continue;
  }

  const projectPath = `Projects - Work/${fileName}.md`;
  let projectRaw;
  try {
    projectRaw = await obsidianGet.call(this, projectPath);
  } catch (e) {
    errors.push(`Failed to fetch ${fileName}: ${e.message}`);
    continue;
  }

  let updatedProject = projectRaw;

  if (patch.proposedStatus) {
    const safeStatus = patch.proposedStatus.trim().replace(/\$/g, '$$');
    updatedProject = updatedProject.replace(
      /(## Current Status\s*\n)([\s\S]*?)(?=\n## |$)/,
      `$1${safeStatus}\n`
    );
  }

  if (patch.newTasks.length > 0) {
    const newTaskLines = patch.newTasks.join('\n');
    // Use a function-form replace to avoid $ interpretation in newTaskLines
    updatedProject = updatedProject.replace(
      /(## Tasks[^\n]*\n[\s\S]*?)(?=\n## |$)/,
      (tasksBlock) => {
        const trailingHr = /\n+---\s*$/.test(tasksBlock);
        const stripped = tasksBlock.replace(/\n+---\s*$/, '').trimEnd();
        return stripped + '\n' + newTaskLines + '\n' + (trailingHr ? '\n---\n' : '');
      }
    );
  }

  try {
    await obsidianPut.call(this, projectPath, updatedProject);
    appliedCount++;
  } catch (e) {
    errors.push(`Failed to write ${fileName}: ${e.message}`);
  }
}

// 6. Remove approved callout blocks from briefing
const approvedRanges = new Set();
for (const patch of patches) {
  for (let i = patch.block.startIdx; i <= patch.block.endIdx; i++) {
    approvedRanges.add(i);
  }
  const prevIdx = patch.block.startIdx - 1;
  if (prevIdx >= 0 && lines[prevIdx].trim() === '') approvedRanges.add(prevIdx);
}

let cleanedBriefing = lines.filter((_, i) => !approvedRanges.has(i)).join('\n');

// 6.5 Update Briefing Overviews for approved projects only
for (const patch of patches) {
  const escapedId = patch.projectId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const overviewRegex = new RegExp(
    `(${escapedId}[\\s\\S]*?)(?:\\*\\*)?Current Status(?:\\*\\*)?[:\\s-]*([\\s\\S]*?)(?=\\n\\n|\\n#|$)`,
    'g'
  );

  if (patch.proposedStatus) {
    cleanedBriefing = cleanedBriefing.replace(overviewRegex, (match, metadata) => {
      return `${metadata.trim()}\n**Current Status**:\n\n${patch.proposedStatus.trim()}`;
    });
  }
}

// 7. Write briefing back
const briefingPath = $('Resolve Briefing Filename').first().json.briefingPath;
try {
  await obsidianPut.call(this, briefingPath.replace(/^vault\//, ''), cleanedBriefing);
} catch (e) {
  errors.push(`Failed to write briefing: ${e.message}`);
}

return [{
  json: {
    status: errors.length === 0 ? 'success' : 'partial',
    message: 'Workflow bypassed the safety check because it detected checked boxes.',
    patches_applied: appliedCount,
    errors,
    // DIAGNOSTIC OUTPUT: See exactly what n8n thought was checked
    debug_checked_blocks_found: patches.map(p => ({
      projectId: p.projectId,
      raw_text_read: p.block.lines.join('\n')
    }))
  }
}];

// List the Overview folder and find the most recent Daily Briefing.
// Strategy: prefer today's date (sharedDate), fall back to the most recent overall.
const OBSIDIAN_BASE = 'https://10.1.1.200:27124';
const token = $('Config - Paths').first().json.obsidianToken;
const sharedDate = $('Config - Paths').first().json.shared_date;

// ── 1. Resolve briefing ──
const overviewResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${OBSIDIAN_BASE}/vault/Overview/`,
  headers: { 'Authorization': 'Bearer ' + token },
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  skipSslCertificateValidation: true
});

if (overviewResponse.statusCode !== 200) {
  throw new Error(`Failed to list Overview folder: HTTP ${overviewResponse.statusCode}`);
}

const overviewFiles = overviewResponse.body.files || [];

const allBriefings = overviewFiles
  .filter(f => /Daily Briefing\.md$/.test(f))
  .sort((a, b) => b.localeCompare(a));

if (allBriefings.length === 0) {
  throw new Error('No Daily Briefing files found in Overview folder');
}

const todayBriefings = allBriefings.filter(f => f.startsWith(sharedDate));
const briefingFilename = todayBriefings.length > 0 ? todayBriefings[0] : allBriefings[0];
const resolvedDate = briefingFilename.substring(0, 10);
const usedFallback = todayBriefings.length === 0;
const briefingPath = `vault/Overview/${briefingFilename}`;

// ── 2. Resolve project index ──
const inboxResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${OBSIDIAN_BASE}/vault/Obsidian/PDA/Inbox/`,
  headers: { 'Authorization': 'Bearer ' + token },
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  skipSslCertificateValidation: true
});

if (inboxResponse.statusCode !== 200) {
  throw new Error(`Failed to list Inbox folder: HTTP ${inboxResponse.statusCode}`);
}

const inboxFiles = inboxResponse.body.files || [];

const allProjectIndexes = inboxFiles
  .filter(f => /^projects-\d{4}-\d{2}-\d{2}\.md$/.test(f))
  .sort((a, b) => b.localeCompare(a));

if (allProjectIndexes.length === 0) {
  throw new Error('No project index files found in Obsidian/PDA/Inbox/');
}

const todayProjectIndexes = allProjectIndexes.filter(f => f.startsWith(`projects-${sharedDate}`));
const projectIndexFilename = todayProjectIndexes.length > 0 ? todayProjectIndexes[0] : allProjectIndexes[0];
const projectIndexPath = `vault/Obsidian/PDA/Inbox/${projectIndexFilename}`;
const projectIndexUsedFallback = todayProjectIndexes.length === 0;

return [{ json: { briefingPath, briefingFilename, resolvedDate, usedFallback, projectIndexPath, projectIndexFilename, projectIndexUsedFallback } }];
